    },
    "description": {
      "type": "string",
      "description": "Long description of the data"
    },
    "citation": {
      "type": "string",
      "description": "This is a citation or doi"
    }
  },
  "required": [
    "runtime_data",
    "source",
    "type",
    "name",
    "version"
  ],
  "definitions": {
