                }
              }
            }
          }
        }
      },
      "required": [
        "winner"
      ],
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "dependencies": {
    "isTest": [
      "results",
      "tiebreak",
      "counts"
